    "solution": {
      "en": {
        "strategy": "Make one sales set of 4 orchid bouquets and 1 rose bouquet.",
        "steps": [
          {
            "title": "Find the value of one set",
            "text": "One set earns 4 × $25 + 1 × $30 = $130."
          },
          {
            "title": "Find how many sets were sold",
            "text": "$390 ÷ $130 = 3 sets. Therefore 3 × 4 = 12 orchid bouquets and 3 × 1 = 3 rose bouquets were sold."
          },
          {
            "title": "Count the flowers",
            "text": "The orchid bouquets contain 12 × 20 = 240 orchids. The rose bouquets contain 3 × 10 = 30 roses. Altogether, 240 + 30 = 270 flowers."
          }
        ],
        "answerCheck": "270 flowers"
      },
      "zh-Hans": {
        "strategy": "把4束兰花和1束玫瑰看成1组销售组合。",
        "steps": [
          {
            "title": "求1组的收入",
            "text": "1组收入是4 × $25 + 1 × $30 = $130。"
          },
          {
            "title": "求销售组数",
            "text": "$390 ÷ $130 = 3组，所以卖出了3 × 4 = 12束兰花和3 × 1 = 3束玫瑰。"
          },
          {
            "title": "计算花的总数",
            "text": "兰花有12 × 20 = 240枝，玫瑰有3 × 10 = 30枝。总数是240 + 30 = 270枝花。"
          }
        ],
        "answerCheck": "总共卖出270枝花。"
      }
    },
